import{_ as t,o,c as d,a2 as a}from"./chunks/framework.C3idr2hZ.js";const u=JSON.parse('{"title":"Pi and porc","description":"","frontmatter":{},"headers":[],"relativePath":"docs/pi.md","filePath":"docs/pi.md","lastUpdated":1794396931000}'),r={name:"docs/pi.md"};function c(s,e,n,i,l,p){return o(),d("div",null,[...e[0]||(e[0]=[a(`<h1 id="pi-and-porc" tabindex="-1">Pi and porc <a class="header-anchor" href="#pi-and-porc" aria-label="Permalink to &quot;Pi and porc&quot;">​</a></h1><p><a href="https://pi.dev" target="_blank" rel="noreferrer">Pi</a> is a terminal coding agent. <code>@orc/pi</code>, called <strong>porc</strong>, makes ORC the engine of a Pi setup. Memories, skills, project context, cron jobs and rules all live in ORC and are used from Pi. porc does not touch Pi&#39;s models or providers.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npm:@orc/pi</span></span></code></pre></div><p>Start Pi in a repository and run <code>/orc</code>. ORC must be running, and <code>orc</code> must be on <code>PATH</code>.</p><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Behavior</th></tr></thead><tbody><tr><td><code>orc</code> tool</td><td>Context, memories, skills, projects, jobs, rules, and any ORC tool through <code>search</code> → <code>describe</code> → <code>invoke</code></td></tr><tr><td>Recall</td><td>A small hidden hint of relevant ORC memories and skills per prompt; nothing is preloaded</td></tr><tr><td>Rules</td><td>ORC rules for the workspace run on Pi <code>tool_call</code>, <code>tool_result</code> and <code>input</code> through <code>orc rules hook pi</code></td></tr><tr><td>Projects</td><td>Detects the ORC project for <code>cwd</code>, including nested folders, or asks you to pick one: existing, new or global</td></tr><tr><td>Theme</td><td><code>porc</code> and <code>porc-light</code>, matching <code>DESIGN.md</code>; apply with <code>/orc-theme</code></td></tr></tbody></table><p>Memories and skills you create from Pi are written to ORC, so other agents and the UI see them. Pi still loads local skills from <code>.agents/skills</code>, <code>.pi/skills</code> and <code>~/.pi/agent/skills</code>, and local skills win on name clashes. ORC skills are fetched on demand and never copied to disk, so there is nothing to sync. Pi sessions are already read by ORC&#39;s session archive.</p><h2 id="ask-for-it-in-chat" tabindex="-1">Ask for it in chat <a class="header-anchor" href="#ask-for-it-in-chat" aria-label="Permalink to &quot;Ask for it in chat&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>remember that staging deploys need a feature flag</span></span>
<span class="line"><span>schedule a dependency audit every Monday at 9</span></span>
<span class="line"><span>block the agent from running ssh</span></span></code></pre></div><p>These map to:</p><table tabindex="0"><thead><tr><th>Request</th><th>Action</th><th>Confirmation</th></tr></thead><tbody><tr><td>remember …</td><td><code>memory_create</code></td><td>none</td></tr><tr><td>schedule …</td><td><code>job_create</code>: a cron job that runs Pi in the current folder</td><td>asks first</td></tr><tr><td>block …</td><td><code>rule_add</code>: activates a new rule revision for the workspace</td><td>asks first</td></tr></tbody></table><p>A rule applies to every agent ORC governs. ORC rules must be enabled in Settings.</p><h2 id="configure" tabindex="-1">Configure <a class="header-anchor" href="#configure" aria-label="Permalink to &quot;Configure&quot;">​</a></h2><p>User config lives at <code>~/.pi/agent/porc.json</code>. Project config lives at <code>.pi/porc.json</code>, and porc reads it only after Pi trusts the project. The full option and environment variable reference is in the <a href="https://github.com/niradler/orc/tree/master/packages/pi#readme" target="_blank" rel="noreferrer">package README</a>.</p><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>apiBase</code></td><td><code>~/.orc/config.json</code> or <code>http://127.0.0.1:7700</code></td><td>ORC API origin</td></tr><tr><td><code>secretEnv</code></td><td>—</td><td>Environment variable that holds the API secret</td></tr><tr><td><code>project</code></td><td>detected</td><td>Fixed ORC project</td></tr><tr><td><code>autoProject</code> / <code>askProject</code></td><td><code>true</code> / <code>true</code></td><td>Detect the project, and prompt when none matches</td></tr><tr><td><code>autoContext</code></td><td><code>true</code></td><td>Inject the context index once per session</td></tr><tr><td><code>rules</code></td><td><code>true</code></td><td>Enforce ORC rules in Pi</td></tr><tr><td><code>transport</code></td><td><code>stdio</code></td><td><code>stdio</code> runs <code>orc mcp</code>; <code>http</code> uses <code>&lt;apiBase&gt;/mcp</code></td></tr><tr><td><code>recall.*</code></td><td>4 memories, 3 skills, 900 chars</td><td>Per-prompt hint budget</td></tr></tbody></table><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><p><code>/orc</code>, <code>/orc-context</code>, <code>/orc-project [name|new|global|auto|reset]</code>, <code>/orc-skills</code>, <code>/orc-remember name | when | content</code>, <code>/orc-doctor</code>, <code>/orc-theme</code>, <code>/orc-reload</code>.</p><p>Session flags: <code>--porc-api-base</code>, <code>--porc-project</code>, <code>--porc-no-context</code>, <code>--porc-no-recall</code>, <code>--porc-no-rules</code>.</p><p>For the MCP and skills setup shared with other agents, see <a href="./connect-agents">Connect agents</a>.</p>`,20)])])}const m=t(r,[["render",c]]);export{u as __pageData,m as default};
